package org.brightstats.stats;
import java.util.*;
import java.nio.file.*;
import com.google.gson.*;
public final class PairwiseChecks {
    private static int checks;
    private static void require(boolean value,String message){checks++;if(!value)throw new AssertionError(message);}
    private static void close(double a,double b,double tolerance){require(Double.isNaN(a)&&Double.isNaN(b)||Math.abs(a-b)<=tolerance*Math.max(1,Math.abs(b)),"Pairwise mismatch: "+a+" / "+b);}
    private static void reject(Runnable action){try{action.run();throw new AssertionError("Invalid pairwise estimator accepted");}catch(IllegalArgumentException expected){checks++;}}
    public static void main(String[] args)throws Exception{Path output=Path.of(args[0]);Files.createDirectories(output);var json=new GsonBuilder().serializeNulls().serializeSpecialFloatingPointValues().setPrettyPrinting().create();Random random=new Random(1985);int n=480;double[][] complete=new double[n][9];for(int row=0;row<n;row++){double x=random.nextGaussian(),m=.4*x+.9*random.nextGaussian(),y=.3*x+.4*m+.8*random.nextGaussian();for(int j=0;j<3;j++){complete[row][j]=2+(.8+.1*j)*x+.8*random.nextGaussian();complete[row][j+3]=5+(.8+.1*j)*m+.8*random.nextGaussian();complete[row][j+6]=10+(.8+.1*j)*y+.8*random.nextGaussian();}}double[][] raw=Matrices.copy(complete);for(int row=0;row<n;row++)for(int col=0;col<9;col++)if(random.nextDouble()<.06)raw[row][col]=Double.NaN;Arrays.fill(raw[0],Double.NaN);List<String> names=List.of("X1","X2","X3","M1","M2","M3","Y1","Y2","Y3");var blocks=List.of(new PlsSem.Block("X",new int[]{0,1,2},PlsSem.Mode.A),new PlsSem.Block("M",new int[]{3,4,5},PlsSem.Mode.A),new PlsSem.Block("Y",new int[]{6,7,8},PlsSem.Mode.A));var paths=List.of(new PlsSem.Edge(0,1),new PlsSem.Edge(0,2),new PlsSem.Edge(1,2));var pls=ComponentScores.Model.pls(blocks,paths,PlsSem.Options.defaults());var prepared=Gsca.fromBlocks(names,blocks,paths);var gsca=ComponentScores.Model.gsca(prepared.model(),Gsca.Options.defaults(),prepared.columns());
        JsonArray cases=new JsonArray();for(String estimator:List.of("PLS","PLSC","GSCA")){var model=estimator.equals("GSCA")?gsca:pls;boolean consistent=estimator.equals("PLSC");var all=PairwiseComponents.fit(complete,names,model,consistent);double[][] expectedPaths=estimator.equals("GSCA")?Gsca.fit(complete,prepared.model(),Gsca.Options.defaults()).paths():consistent?ConsistentPls.fit(complete,blocks,paths,PlsSem.Options.defaults()).paths():PlsSem.fit(complete,blocks,paths,PlsSem.Options.defaults()).pathCoefficients();for(var path:paths)close(all.paths()[path.source()][path.target()],expectedPaths[path.source()][path.target()],2e-6);var boot=PairwiseComponents.bootstrap(raw,names,model,consistent,new Bootstrap.Options(40,883,.95),null);require(boot.inference().successful()>=32,"Too few usable pairwise draws");require(boot.point().moments().emptyRows()==1,"Empty source row undisclosed");JsonObject record=new JsonObject();record.addProperty("estimator",estimator);record.add("observations",json.toJsonTree(raw));record.add("complete",json.toJsonTree(complete));record.add("columnNames",json.toJsonTree(names));record.add("model",json.toJsonTree(model));record.addProperty("consistent",consistent);record.add("point",json.toJsonTree(boot.point()));record.add("bootstrap",json.toJsonTree(boot.inference()));cases.add(record);}
        var bca=PairwiseComponents.bootstrap(raw,names,pls,false,new Bootstrap.Options(40,117,.90,BootstrapIntervals.Method.BCA,RegressionBootstrap.Convention.STANDARD,true),null);JsonObject extra=cases.get(0).getAsJsonObject().deepCopy();extra.addProperty("estimator","PLS_BCA");extra.add("point",json.toJsonTree(bca.point()));extra.add("bootstrap",json.toJsonTree(bca.inference()));cases.add(extra);
        var sem=SemModel.reflective(names,complete,blocks,paths,true,false).model();var semOptions=new CovarianceSem.Options(1000,1e-8,1e-12,CovarianceSem.Likelihood.WISHART,false,.95);var allSem=PairwiseSem.fit(complete,names,sem,semOptions);var ordinary=CovarianceSem.fit(complete,sem,semOptions);for(int i=0;i<ordinary.estimates().length;i++)close(allSem.estimates()[i],ordinary.estimates()[i],3e-6);var semBoot=PairwiseSem.bootstrap(raw,names,sem,semOptions,new Bootstrap.Options(40,883,.95),null);require(semBoot.inference().successful()>=32,"Pairwise SEM replicate accounting");JsonObject semCase=new JsonObject();semCase.add("observations",json.toJsonTree(raw));semCase.add("complete",json.toJsonTree(complete));semCase.add("columnNames",json.toJsonTree(names));semCase.add("model",json.toJsonTree(sem));semCase.add("options",json.toJsonTree(semOptions));semCase.add("point",json.toJsonTree(semBoot.point()));semCase.add("bootstrap",json.toJsonTree(semBoot.inference()));
        require(!CovarianceSem.properDisturbance(new double[][]{{1e-16,1.5e-16},{1.5e-16,1e-16}},new double[][]{{1e-16,1.5e-16},{1.5e-16,1e-16}}),"Small-unit indefinite disturbances escaped detection");require(CovarianceSem.properDisturbance(new double[][]{{1e-16,.5e-16},{.5e-16,1e-16}},new double[][]{{1e-16,.5e-16},{.5e-16,1e-16}}),"Small-unit valid disturbances rejected");require(CovarianceSem.properDisturbance(new double[][]{{0,0},{0,1}},new double[][]{{0,0},{0,1}}),"Fixed zero-variance component should remain semidefinite");
        double[][] tiny=Matrices.copy(complete);for(var row:tiny)for(int j=0;j<row.length;j++)row[j]*=1e-8;require(PairwiseMoments.covarianceAdmissible(PairwiseMoments.fit(tiny,names).covariance()),"Covariance admissibility must be unit invariant");var tinyModel=SemModel.reflective(names,tiny,blocks,paths,true,false).model();var tinyFit=PairwiseSem.fit(tiny,names,tinyModel,semOptions);require(tinyFit.converged(),"Small-unit SEM did not converge");close(tinyFit.discrepancy(),allSem.discrepancy(),1e-8);
        double[][] invalid={{1,1,Double.NaN},{-1,-1,Double.NaN},{1,Double.NaN,1},{-1,Double.NaN,-1},{Double.NaN,1,-1},{Double.NaN,-1,1}};var indefinite=PairwiseMoments.fit(invalid,List.of("A","B","C"));close(indefinite.correlation()[0][1],1,1e-14);require(indefinite.correlationMinimumEigenvalue()<0,"Indefinite pairwise matrix hidden");reject(()->PairwiseMoments.design(indefinite));double[][] zero={{0,Double.NaN},{1,2},{2,3}};double[][] unpacked=PairwiseMoments.unpack(PairwiseMoments.pack(zero));require(Arrays.deepEquals(zero,unpacked),"Observed zero confused with missing mask");double[][] inf=Matrices.copy(raw);inf[1][1]=Double.POSITIVE_INFINITY;reject(()->PairwiseMoments.fit(inf,names));Thread.currentThread().interrupt();try{PairwiseMoments.fit(raw,names);throw new AssertionError("Cancellation ignored");}catch(java.util.concurrent.CancellationException expected){checks++;}finally{Thread.interrupted();}Files.writeString(output.resolve("components.json"),json.toJson(cases));Files.writeString(output.resolve("sem.json"),json.toJson(semCase));JsonObject failure=new JsonObject();failure.add("observations",json.toJsonTree(invalid));failure.add("point",json.toJsonTree(indefinite));Files.writeString(output.resolve("indefinite.json"),json.toJson(failure));System.out.println("Pairwise checks: "+checks);}
}
